                  task.data[6] = MVSTATE_INTRO_MSG_1;
                  GetMonData(mon, MON_DATA_NICKNAME, nickname);
                  StringCopy_Nickname(gBattleTextBuff1, nickname);

                  if (_var == MON_HAS_MAX_MOVES)
                      task.data[0] = EVOSTATE_REPLACE_MOVE;
