/** Source: evolution_scene.c → CB2_EvolutionSceneLoadGraphics */
export const CB2_EvolutionSceneLoadGraphics: CB2Callback = (rt) => {
  let id = 0;
      let pokePal: any = null;
      let postEvoSpecies = 0;
      let trainerId, personality;
      let mon: any = gPlayerParty[_gt(rt, sEvoStructPtr.evoTaskId).data[10]];

      postEvoSpecies = _gt(rt, sEvoStructPtr.evoTaskId).data[2];
      trainerId = GetMonData(mon, MON_DATA_OT_ID);
      personality = GetMonData(mon, MON_DATA_PERSONALITY);

      SetHBlankCallback(null);
      /* noop SetVBlankCallback */;
      CpuFill32(0, (VRAM), VRAM_SIZE);

      rt.SetGpuReg(REG_OFFSET_MOSAIC, 0);
      rt.SetGpuReg(REG_OFFSET_WIN0H, 0);
      rt.SetGpuReg(REG_OFFSET_WIN0V, 0);
      rt.SetGpuReg(REG_OFFSET_WIN1H, 0);
      rt.SetGpuReg(REG_OFFSET_WIN1V, 0);
      rt.SetGpuReg(REG_OFFSET_WININ, 0);
      rt.SetGpuReg(REG_OFFSET_WINOUT, 0);

      ResetPaletteFade();

      gBattle_BG0_X = 0;
      gBattle_BG0_Y = 0;
      (globalThis as any).gBattle_BG1_X = 0;
      (globalThis as any).gBattle_BG1_Y = 0;
      gBattle_BG2_X = 0;
      gBattle_BG2_Y = 0;
      gBattle_BG3_X = 256;
      gBattle_BG3_Y = 0;

      gBattleEnvironment = BATTLE_ENVIRONMENT_PLAIN;

      InitBattleBgsVideo();
      LoadBattleTextboxAndBackground();
      rt.ResetSpriteData();
      FreeAllSpritePalettes();
      (globalThis as any).gReservedSpritePaletteCount = 4;

      DecompressPicFromTable_2(gMonFrontPicTable[postEvoSpecies],
                               gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_RIGHT],
                               postEvoSpecies);
      pokePal = GetMonSpritePalStructFromOtIdPersonality(postEvoSpecies, trainerId, personality);

      LoadCompressedPalette(pokePal.data, OBJ_PLTT_ID(2), PLTT_SIZE_4BPP);

      SetMultiuseSpriteTemplateToPokemon(postEvoSpecies, B_POSITION_OPPONENT_RIGHT);
      gMultiuseSpriteTemplate.affineAnims = gDummySpriteAffineAnimTable;
      sEvoStructPtr.postEvoSpriteId = id = rt.CreateSpriteFromTemplate('gMultiuseSpriteTemplate',  120, 64, 30);

      rt.setSpriteCallback(id, SpriteCallbackDummy_2);
      rt.gba.oam[_gs(rt, id).oamIndex].paletteBank = 2;

      rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_BG_ALL_ON | DISPCNT_OBJ_1D_MAP);

      SetHBlankCallback(EvoDummyFunc);
      /* noop SetVBlankCallback */;
      /* TODO scene transition: SetMainCallback2(CB2_EvolutionSceneUpdate) */;

      rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");

      ShowBg(0);
      ShowBg(1);
      ShowBg(2);
      ShowBg(3);
};

/** Source: evolution_scene.c → CB2_TradeEvolutionSceneLoadGraphics */
export const CB2_TradeEvolutionSceneLoadGraphics: CB2Callback = (rt) => {
  let mon: any = gPlayerParty[_gt(rt, sEvoStructPtr.evoTaskId).data[10]];
      let postEvoSpecies = _gt(rt, sEvoStructPtr.evoTaskId).data[2];

      switch (gMain.state)
      {
      case 0:
          rt.SetGpuReg(REG_OFFSET_DISPCNT, 0);
          SetHBlankCallback(null);
          /* noop SetVBlankCallback */;
          rt.ResetSpriteData();
          FreeAllSpritePalettes();
          (globalThis as any).gReservedSpritePaletteCount = 4;
          gBattle_BG0_X = 0;
          gBattle_BG0_Y = 0;
          (globalThis as any).gBattle_BG1_X = 0;
          (globalThis as any).gBattle_BG1_Y = 0;
          gBattle_BG2_X = 0;
          gBattle_BG2_Y = 0;
          gBattle_BG3_X = 256;
          gBattle_BG3_Y = 0;
          gMain.state++;
          break;
      case 1:
          ResetPaletteFade();
          SetHBlankCallback(EvoDummyFunc);
          /* noop SetVBlankCallback */;
          gMain.state++;
          break;
      case 2:
          LoadTradeAnimGfx();
          gMain.state++;
          break;
      case 3:
          FillBgTilemapBufferRect(1, 0, 0, 0, 0x20, 0x20, 0x11);
          CopyBgTilemapBufferToVram(1);
          gMain.state++;
          break;
      case 4:
          {
              let pokePal: any = null;
              let trainerId = GetMonData(mon, MON_DATA_OT_ID);
              let personality = GetMonData(mon, MON_DATA_PERSONALITY);
              DecompressPicFromTable_2(gMonFrontPicTable[postEvoSpecies],
                                       gMonSpritesGfxPtr.sprites.ptr[B_POSITION_OPPONENT_RIGHT],
                                       postEvoSpecies);
              pokePal = GetMonSpritePalStructFromOtIdPersonality(postEvoSpecies, trainerId, personality);
              LoadCompressedPalette(pokePal.data, OBJ_PLTT_ID(2), PLTT_SIZE_4BPP);
              gMain.state++;
          }
          break;
      case 5:
          {
              let id = 0;

              SetMultiuseSpriteTemplateToPokemon(postEvoSpecies, B_POSITION_OPPONENT_LEFT);
              gMultiuseSpriteTemplate.affineAnims = gDummySpriteAffineAnimTable;
              sEvoStructPtr.postEvoSpriteId = id = rt.CreateSpriteFromTemplate('gMultiuseSpriteTemplate',  120, 64, 30);

              rt.setSpriteCallback(id, SpriteCallbackDummy_2);
              rt.gba.oam[_gs(rt, id).oamIndex].paletteBank = 2;
              gMain.state++;
              LinkTradeDrawWindow();
          }
          break;
      case 6:
          if (gWirelessCommType)
          {
              LoadWirelessStatusIndicatorSpriteGfx();
              CreateWirelessStatusIndicatorSprite(0, 0);
          }
          BlendPalettes(PALETTES_ALL, 0x10, RGB_BLACK);
          gMain.state++;
          break;
      case 7:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0x10, 0, "RGB_BLACK");
          InitTradeSequenceBgGpuRegs();
          ShowBg(0);
          ShowBg(1);
          /* TODO scene transition: SetMainCallback2(CB2_TradeEvolutionSceneUpdate) */;
          rt.SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_OBJ_ON | DISPCNT_BG0_ON | DISPCNT_BG1_ON | DISPCNT_OBJ_1D_MAP);
          break;
      }
};

